@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

@inject ShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>📦 Dispatcher Dashboard</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <label class="form-label">Filter by Status</label>
        <select class="form-select" @bind="selectedFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-4">
        <label class="form-label">Search</label>
        <input type="text" class="form-control" placeholder="Tracking #, recipient, destination..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4 d-flex align-items-end">
        <button class="btn btn-primary me-2" @onclick="LoadShipments">
            🔄 Refresh
        </button>
        <button class="btn btn-success" @onclick="ToggleNewShipmentForm">
            ➕ New Shipment
        </button>
    </div>
</div>

@if (showNewForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Recipient Name" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                </div>
                <div class="col-md-3">
                    <input type="number" step="0.1" class="form-control" placeholder="Weight (kg)" @bind="newShipment.WeightKg" />
                </div>
                <div class="col-md-3">
                    <label class="form-label small">Estimated Delivery</label>
                    <input type="date" class="form-control" @bind="estimatedDeliveryDate" />
                </div>
                <div class="col-md-3 d-flex align-items-end">
                    <button class="btn btn-primary me-2" @onclick="CreateShipment">Create</button>
                    <button class="btn btn-secondary" @onclick="ToggleNewShipmentForm">Cancel</button>
                </div>
            </div>
            @if (!string.IsNullOrEmpty(createMessage))
            {
                <div class="alert alert-info mt-2">@createMessage</div>
            }
        </div>
    </div>
}

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (FilteredShipments.Count == 0)
{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Weight</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td>@shipment.RecipientName</td>
                        <td>@shipment.WeightKg.ToString("F1") kg</td>
                        <td>
                            <span class="badge @GetStatusBadgeClass(shipment.Status)">
                                @shipment.Status
                            </span>
                        </td>
                        <td>@(shipment.EstimatedDeliveryUtc?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Cancelled)
                            {
                                <select class="form-select form-select-sm d-inline-block w-auto"
                                        @onchange="e => UpdateStatus(shipment, e)">
                                    <option value="">Update...</option>
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        if (status != shipment.Status)
                                        {
                                            <option value="@((int)status)">@status</option>
                                        }
                                    }
                                </select>
                            }
                            else
                            {
                                <span class="text-muted">—</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <div class="row mt-3">
        <div class="col">
            <span class="badge bg-secondary me-1">Total: @FilteredShipments.Count</span>
            @foreach (var g in FilteredShipments.GroupBy(s => s.Status))
            {
                <span class="badge @GetStatusBadgeClass(g.Key) me-1">@g.Key: @g.Count()</span>
            }
        </div>
    </div>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string selectedFilter = "";
    private string searchTerm = "";
    private bool showNewForm;
    private ShipmentDto newShipment = new();
    private DateTime? estimatedDeliveryDate;
    private string createMessage = "";

    private List<ShipmentDto> FilteredShipments
    {
        get
        {
            var result = shipments.AsEnumerable();

            if (Enum.TryParse<ShipmentStatus>(selectedFilter, out var statusFilter))
                result = result.Where(s => s.Status == statusFilter);

            if (!string.IsNullOrWhiteSpace(searchTerm))
            {
                var term = searchTerm.Trim();
                result = result.Where(s =>
                    s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                    s.Origin.Contains(term, StringComparison.OrdinalIgnoreCase));
            }

            return result.ToList();
        }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch
        {
            shipments = [];
        }
        loading = false;
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            var success = await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            if (success)
            {
                shipment.Status = newStatus;
                if (newStatus == ShipmentStatus.Delivered)
                    shipment.DeliveredAtUtc = DateTime.UtcNow;
            }
        }
    }

    private void ToggleNewShipmentForm()
    {
        showNewForm = !showNewForm;
        if (showNewForm)
        {
            newShipment = new();
            estimatedDeliveryDate = DateTime.Today.AddDays(5);
            createMessage = "";
        }
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.Origin) ||
            string.IsNullOrWhiteSpace(newShipment.Destination) ||
            string.IsNullOrWhiteSpace(newShipment.RecipientName))
        {
            createMessage = "Please fill in origin, destination, and recipient.";
            return;
        }

        newShipment.EstimatedDeliveryUtc = estimatedDeliveryDate?.ToUniversalTime();
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        if (created is not null)
        {
            shipments.Insert(0, created);
            showNewForm = false;
            createMessage = "";
        }
        else
        {
            createMessage = "Failed to create shipment. Please try again.";
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-success",
        ShipmentStatus.Delivered => "bg-dark",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/"
@page "/track"
@page "/track/{TrackingId}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto

@inject ShipmentService ShipmentService

<PageTitle>Track Shipment - ShipmentTracker</PageTitle>

<div class="text-center mb-4">
    <h2>📦 ShipmentTracker</h2>
    <p class="lead">Track your shipment in real time</p>
</div>

<div class="row justify-content-center mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control form-control-lg" placeholder="Enter tracking number (e.g., SHP-20260601-1001)"
                   @bind="trackingInput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@tracking">
                @if (tracking)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                🔍 Track
            </button>
        </div>
    </div>
</div>

@if (notFound)
