@page "/"
@page "/track"
@page "/track/{TrackingId}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto

@inject ShipmentService ShipmentService

<PageTitle>Track Shipment - ShipmentTracker</PageTitle>

<div class="text-center mb-4">
    <h2>📦 ShipmentTracker</h2>
    <p class="lead">Track your shipment in real time</p>
</div>

<div class="row justify-content-center mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control form-control-lg" placeholder="Enter tracking number (e.g., SHP-20260601-1001)"
                   @bind="trackingInput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@tracking">
                @if (tracking)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                🔍 Track
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="row justify-content-center">
        <div class="col-md-6">
            <div class="alert alert-warning text-center">
                <strong>Shipment not found.</strong> Please check your tracking number and try again.
            </div>
        </div>
    </div>
}

@if (shipment is not null)
{
    <div class="row justify-content-center">
        <div class="col-md-8">
            <div class="card shadow">
                <div class="card-header bg-dark text-white d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">Tracking: <code class="text-light">@shipment.TrackingNumber</code></h5>
                    <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
                </div>
                <div class="card-body">
                    <div class="row mb-3">
                        <div class="col-md-6">
                            <strong>From:</strong> @shipment.Origin
                        </div>
                        <div class="col-md-6">
                            <strong>To:</strong> @shipment.Destination
                        </div>
                    </div>
                    <div class="row mb-3">
                        <div class="col-md-6">
                            <strong>Recipient:</strong> @shipment.RecipientName
                        </div>
                        <div class="col-md-6">
                            <strong>Weight:</strong> @shipment.WeightKg.ToString("F1") kg
                        </div>
                    </div>
                    <div class="row mb-3">
                        <div class="col-md-6">
                            <strong>Description:</strong> @shipment.Description
                        </div>
                        <div class="col-md-6">
                            <strong>Shipped:</strong> @shipment.CreatedAtUtc.ToString("MMM dd, yyyy HH:mm") UTC
                        </div>
                    </div>

                    <hr />

                    @if (shipment.Status == ShipmentStatus.Delivered)
                    {
                        <div class="alert alert-success mb-0">
                            <h5>✅ Delivered</h5>
                            <p class="mb-0">Your shipment was delivered on <strong>@shipment.DeliveredAtUtc?.ToString("MMM dd, yyyy HH:mm") UTC</strong>.</p>
                        </div>
                    }
                    else if (shipment.Status == ShipmentStatus.Cancelled)
                    {
                        <div class="alert alert-danger mb-0">
                            <h5>❌ Cancelled</h5>
                            <p class="mb-0">This shipment has been cancelled.</p>
                        </div>
                    }
                    else
                    {
                        <div class="alert alert-info mb-0">
                            <h5>🚚 Estimated Delivery</h5>
                            @if (shipment.EstimatedDeliveryUtc.HasValue)
                            {
                                var daysLeft = (shipment.EstimatedDeliveryUtc.Value - DateTime.UtcNow).Days;
                                <p class="mb-0">
                                    <strong>@shipment.EstimatedDeliveryUtc.Value.ToString("MMM dd, yyyy")</strong>
                                    @if (daysLeft > 0)
                                    {
                                        <span> — @daysLeft day(s) from now</span>
                                    }
                                    else if (daysLeft == 0)
                                    {
                                        <span> — arriving today!</span>
                                    }
                                    else
                                    {
                                        <span class="text-danger"> — delayed</span>
                                    }
                                </p>
                            }
                            else
                            {
                                <p class="mb-0">No estimated delivery date available.</p>
                            }
                        </div>
                    }

                    <!-- Progress tracker -->
                    <div class="mt-4">
                        <h6>Shipment Progress</h6>
                        <div class="progress" style="height: 30px;">
                            <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                                 role="progressbar"
                                 style="width: @(GetProgressPercent(shipment.Status))%"
                                 aria-valuenow="@GetProgressPercent(shipment.Status)"
                                 aria-valuemin="0" aria-valuemax="100">
                                @shipment.Status
                            </div>
                        </div>
                        <div class="d-flex justify-content-between mt-1 small text-muted">
                            <span>Pending</span>
                            <span>Picked Up</span>
                            <span>In Transit</span>
                            <span>Out for Delivery</span>
                            <span>Delivered</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public string? TrackingId { get; set; }

    private string trackingInput = "";
    private ShipmentDto? shipment;
    private bool notFound;
    private bool tracking;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingId))
        {
            trackingInput = TrackingId;
            await TrackShipment();
        }
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingInput))
            return;

        tracking = true;
        notFound = false;
        shipment = null;

        try
        {
            shipment = await ShipmentService.GetByTrackingNumberAsync(trackingInput.Trim());
            notFound = shipment is null;
        }
        catch
        {
            notFound = true;
        }

        tracking = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-success",
        ShipmentStatus.Delivered => "bg-dark",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 0,
        _ => 0
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Cancelled => "bg-danger",
        ShipmentStatus.Delivered => "bg-dark",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };
}

